1	//! Git access by shelling the real `git` binary through a
2	//! [`callisto_model::CommandRunner`].
3	
4	use std::path::{Path, PathBuf};
5	
6	use callisto_model::{ApplyPermit, CommandRunner, CommitSha, StagedChangeKindV1, StagedChangeV1, TagName};
7	
8	use crate::{GitCommit, TagSignPolicy, VcsError};
9	
10	/// Record separator placed immediately before each commit's fields in
11	/// `git log --format=` output, so a commit message containing `\n` can
12	/// never be mistaken for a record boundary.
13	const RECORD_SEP: char = '\u{1e}';
14	
15	/// Unit separator between a commit's sha and its raw message body in
16	/// `git log --format=` output.
17	const FIELD_SEP: char = '\u{1f}';
18	
19	/// Every Git read and write callisto performs, each one `git` subprocess
20	/// run in `root` through a [`CommandRunner`].
21	pub struct GitAccess<'r> {
22	    runner: &'r dyn CommandRunner,
23	    root: PathBuf,
24	}
25	
26	/// Fresh Git checkout facts used to bind a durable release intent to the
27	/// exact repository it was validated against.
28	///
29	/// This is intentionally evidence, not a lossy `bool`: consumers must retain
30	/// the canonical root and complete `HEAD` they compare to source identity.
31	/// Its fields are private so only the VCS observation path can construct it.
32	#[derive(Debug, PartialEq, Eq)]
33	pub struct GitCommitTrustEvidence {
34	    canonical_root: PathBuf,
35	    head: CommitSha,
36	    head_disposition: GitHeadDisposition,
37	}
38	
39	impl GitCommitTrustEvidence {
40	    pub(crate) fn new(canonical_root: PathBuf, head: CommitSha, head_disposition: GitHeadDisposition) -> Self {
41	        Self {
42	            canonical_root,
43	            head,
44	            head_disposition,
45	        }
46	    }
47	
48	    pub fn canonical_root(&self) -> &Path {
49	        &self.canonical_root
50	    }
51	
52	    pub fn head(&self) -> &CommitSha {
53	        &self.head
54	    }
55	
56	    pub fn head_disposition(&self) -> GitHeadDisposition {
57	        self.head_disposition
58	    }
59	
60	    /// The checkout facts a durable release intent is bound to.
61	    pub fn identity(&self) -> GitCommitTrustIdentity<'_> {
62	        GitCommitTrustIdentity {
63	            canonical_root: &self.canonical_root,
64	            head: &self.head,
65	            head_disposition: self.head_disposition,
66	        }
67	    }
68	}
69	
70	/// Borrowed identity view of a [`GitCommitTrustEvidence`]; see
71	/// [`GitCommitTrustEvidence::identity`].
72	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
73	pub struct GitCommitTrustIdentity<'a> {
74	    pub canonical_root: &'a Path,
75	    pub head: &'a CommitSha,
76	    pub head_disposition: GitHeadDisposition,
77	}
78	
79	/// Whether `HEAD` was attached to a symbolic reference when it was observed.
80	/// A detached checkout is valid when its full [`CommitSha`] matches the
81	/// release intent's source identity.
82	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
83	pub enum GitHeadDisposition {
84	    Attached,
85	    Detached,
86	}
87	
88	impl<'r> GitAccess<'r> {
89	    pub fn new(root: impl Into<PathBuf>, runner: &'r dyn CommandRunner) -> Self {
90	        GitAccess {
91	            runner,
92	            root: root.into(),
93	        }
94	    }
95	
96	    /// Returns every staged (Git index) change relative to `base`. File
97	    /// contents for additions and modifications are read directly from the
98	    /// worktree with [`std::fs::read`], never through a [`CommandRunner`]
99	    /// (whose captured stdout is a lossy `String`), so CRLF and binary
100	    /// content survive exactly.
101	    pub fn staged_changes_since(&self, base: &CommitSha) -> Result<Vec<StagedChangeV1>, VcsError> {
102	        let output = self.runner.run(
103	            "git",
104	            &["diff", "--cached", "--raw", "-z", "--no-renames", base.as_str()],
105	            &self.root,
106	        )?;
107	        if !output.success() {
108	            return Err(VcsError::Git(format!(
109	                "`git diff --cached --raw` against `{}` failed: {}",
110	                base.as_str(),
111	                output.redacted_stderr()
112	            )));
113	        }
114	
115	        let entries = parse_raw_diff_z(&output.stdout)?;
116	        let mut changes = Vec::with_capacity(entries.len());
117	        for entry in entries {
118	            let kind = staged_change_kind(entry.status);
119	            let contents = match kind {
120	                StagedChangeKindV1::Added | StagedChangeKindV1::Modified => {
121	                    let bytes = std::fs::read(self.root.join(&entry.path)).map_err(|error| {
122	                        VcsError::Git(format!("could not read staged file `{}`: {error}", entry.path))
123	                    })?;
124	                    Some(bytes)
125	                }
126	                _ => None,
127	            };
128	            changes.push(StagedChangeV1 {
129	                path: entry.path,
130	                kind,
131	                new_mode: entry.new_mode,
132	                contents,
133	            });
134	        }
135	        Ok(changes)
136	    }
137	
138	    /// Returns explicit, fresh Git trust evidence for a durable release.
139	    /// Errors omit raw stderr; ignored paths (build output) are allowed.
140	    pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
141	        let root = self.runner.run("git", &["rev-parse", "--show-toplevel"], &self.root)?;
142	        if !root.success() {
143	            return Err(VcsError::Git(
144	                "could not determine the Git repository root for release trust".to_string(),
145	            ));
146	        }
147	        let canonical_root = canonical_git_root(root.stdout_trimmed())?;
148	
149	        let object_format = self
150	            .runner
151	            .run("git", &["rev-parse", "--show-object-format"], &self.root)?;
152	        if !object_format.success() || object_format.stdout_trimmed() != "sha1" {
153	            return Err(VcsError::Git(
154	                "release trust requires a SHA-1 Git object format".to_string(),
155	            ));
156	        }
157	        let shallow = self
158	            .runner
159	            .run("git", &["rev-parse", "--is-shallow-repository"], &self.root)?;
160	        if !shallow.success() || shallow.stdout_trimmed() != "false" {
161	            return Err(VcsError::Git(
162	                "release trust requires a complete, non-shallow Git repository".to_string(),
163	            ));
164	        }
165	
166	        let head = self
167	            .runner
168	            .run("git", &["rev-parse", "--verify", "HEAD^{commit}"], &self.root)?;
169	        if !head.success() {
170	            return Err(VcsError::Git(
171	                "could not resolve a commit for release trust".to_string(),
172	            ));
173	        }
174	        let head = CommitSha::parse(head.stdout_trimmed()).map_err(|error| {
175	            drop(error);
176	            VcsError::Git("Git returned an invalid full HEAD commit for release trust".to_string())
177	        })?;
178	
179	        let symbolic_head = self
180	            .runner
181	            .run("git", &["symbolic-ref", "--quiet", "HEAD"], &self.root)?;
182	        let head_disposition = match symbolic_head.exit_code {
183	            Some(0) => GitHeadDisposition::Attached,
184	            Some(1) => GitHeadDisposition::Detached,
185	            _ => {
186	                return Err(VcsError::Git(
187	                    "could not determine the symbolic HEAD state for release trust".to_string(),
188	                ))
189	            }
190	        };
191	
192	        let status = self.runner.run(
193	            "git",
194	            &["status", "--porcelain=v1", "-z", "--untracked-files=all"],
195	            &self.root,
196	        )?;
197	        if !status.success() {
198	            return Err(VcsError::Git(
199	                "could not inspect the worktree for release trust".to_string(),
200	            ));
201	        }
202	        check_release_worktree_status(&status.stdout)?;
203	
204	        Ok(GitCommitTrustEvidence::new(canonical_root, head, head_disposition))
205	    }
206	}
207	
208	/// One `git diff --raw -z` record, before Git's single-letter status is
209	/// mapped to a [`StagedChangeKindV1`] and file contents are read.
210	struct RawDiffEntry {
211	    path: String,
212	    /// The post-image Git file mode, or `None` for a pure deletion.
213	    new_mode: Option<u32>,
214	    status: char,
215	}
216	
217	/// Parses `git diff --raw -z --no-renames` output. Each record is two
218	/// `\0`-separated tokens: a `:<old-mode> <new-mode> <old-sha> <new-sha>
219	/// <status>` metadata line, then the path. `--no-renames` guarantees at
220	/// most one path per record (a rename or copy would otherwise emit two).
221	fn parse_raw_diff_z(raw: &str) -> Result<Vec<RawDiffEntry>, VcsError> {
222	    let mut entries = Vec::new();
223	    let mut tokens = raw.split('\0').filter(|token| !token.is_empty());
224	    while let Some(meta) = tokens.next() {
225	        let Some(meta) = meta.strip_prefix(':') else {
226	            return Err(VcsError::Git(format!(
227	                "unexpected token in `git diff --raw -z` output: {meta:?}"
228	            )));
229	        };
230	        let path = tokens.next().ok_or_else(|| {
231	            VcsError::Git("truncated `git diff --raw -z` output: missing a path after its metadata line".to_string())
232	        })?;
233	        let fields: Vec<&str> = meta.split(' ').collect();
234	        let [_old_mode, new_mode, _old_sha, _new_sha, status_field] = fields.as_slice() else {
235	            return Err(VcsError::Git(format!(
236	                "malformed `git diff --raw -z` metadata line: {meta:?}"
237	            )));
238	        };
239	        let status = status_field
240	            .chars()
241	            .next()
242	            .ok_or_else(|| VcsError::Git(format!("empty status in `git diff --raw -z` metadata line: {meta:?}")))?;
243	        let new_mode =
244	            if status == 'D' {
245	                None
246	            } else {
247	                Some(u32::from_str_radix(new_mode, 8).map_err(|error| {
248	                    VcsError::Git(format!("invalid Git mode `{new_mode}` in raw diff output: {error}"))
249	                })?)
250	            };
251	        entries.push(RawDiffEntry {
252	            path: path.to_string(),
253	            new_mode,
254	            status,
255	        });
256	    }
257	    Ok(entries)
258	}
259	
260	/// Maps a `git diff --raw` single-letter status to a [`StagedChangeKindV1`].
261	/// Any status this codebase does not have a named case for (Git's own docs
262	/// list `X` as "unknown") conservatively maps to `Unmerged`, which
263	/// [`callisto_model::ReleasePrCommitPlanV1::from_changes`] always rejects --
264	/// safe by construction rather than by an exhaustive status list here.
265	fn staged_change_kind(status: char) -> StagedChangeKindV1 {
266	    match status {
267	        'A' => StagedChangeKindV1::Added,
268	        'M' => StagedChangeKindV1::Modified,
269	        'D' => StagedChangeKindV1::Deleted,
270	        'R' => StagedChangeKindV1::Renamed,
271	        'C' => StagedChangeKindV1::Copied,
272	        'T' => StagedChangeKindV1::TypeChanged,
273	        _ => StagedChangeKindV1::Unmerged,
274	    }
275	}
276	
277	fn canonical_git_root(raw_root: &str) -> Result<PathBuf, VcsError> {
278	    if raw_root.is_empty() {
279	        return Err(VcsError::Git(
280	            "Git returned an empty repository root for release trust".to_string(),
281	        ));
282	    }
283	    dunce::canonicalize(raw_root).map_err(|error| {
284	        drop(error);
285	        VcsError::Git("could not canonicalize the Git repository root for release trust".to_string())
286	    })
287	}
288	
289	/// Ignored paths are build output and never block; tracked or untracked changes do.
290	fn check_release_worktree_status(status: &str) -> Result<(), VcsError> {
291	    match status.split('\0').find(|record| !record.is_empty()) {
292	        None => Ok(()),
293	        Some(record) => Err(VcsError::Git(format!(
294	            "release trust requires a clean worktree; found `{}`",
295	            record.get(3..).unwrap_or(record)
296	        ))),
297	    }
298	}
299	
300	impl GitAccess<'_> {
301	    /// Returns the commit SHA that `HEAD` currently resolves to.
302	    pub fn head_sha(&self) -> Result<CommitSha, VcsError> {
303	        let output = self.runner.run("git", &["rev-parse", "HEAD"], &self.root)?;
304	        if !output.success() {
305	            return Err(VcsError::Git(format!(
306	                "`git rev-parse HEAD` failed in `{}`: {}",
307	                self.root.display(),
308	                output.redacted_stderr()
309	            )));
310	        }
311	        let sha_str = output.stdout_trimmed();
312	        CommitSha::parse(sha_str).map_err(|e| VcsError::Git(format!("could not parse HEAD SHA `{sha_str}`: {e}")))
313	    }
314	
315	    /// Lists tag names, optionally filtered by `glob` (a [`globset::Glob`]
316	    /// pattern; `None` matches every tag).
317	    ///
318	    /// Always fetches the full tag list and filters locally with the same
319	    /// `globset` matcher `callisto-graph`'s `tags::matching_tags` uses, never
320	    /// `git tag --list <pattern>`'s different glob dialect.
321	    pub fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
322	        let output = self.runner.run("git", &["tag", "--list"], &self.root)?;
323	        if !output.success() {
324	            // A directory with no `.git` anywhere in its ancestry is not a
325	            // hard failure -- it's the normal shape of a brand-new/pre-git
326	            // package, and callers (e.g. `status`) treat "no tags" as
327	            // "unreleased" rather than aborting. Any OTHER failure (a
328	            // corrupted or locked repository, a permissions error, ...)
329	            // must still surface as a real error rather than silently
330	            // becoming "zero tags".
331	            if !output.stderr.contains("not a git repository") {
332	                return Err(VcsError::Git(format!(
333	                    "`git tag --list` failed in `{}`: {}",
334	                    self.root.display(),
335	                    output.redacted_stderr()
336	                )));
337	            }
338	        }
339	        let all = output.stdout_lines().map(|s| s.to_string());
340	
341	        let matcher = glob.map(crate::compile_tag_glob).transpose()?;
342	
343	        Ok(all
344	            .filter(|t| matcher.as_ref().is_none_or(|m| m.is_match(t)))
345	            // A legal Git ref is not necessarily safe as a bare CLI positional (a leading `-`).
346	            .filter_map(|t| TagName::parse(&t).ok())
347	            .collect())
348	    }
349	
350	    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
351	    /// it points at. An unresolvable ref resolves to `Ok(None)`, which
352	    /// callers treat as "no bound" / "infer over full history".
353	    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
354	        let rev = format!("{refname}^{{commit}}");
355	        let output = self
356	            .runner
357	            .run("git", &["rev-parse", "--verify", "--quiet", &rev], &self.root)?;
358	
359	        if !output.success() {
360	            return Ok(None);
361	        }
362	        let sha_str = output.stdout_trimmed();
363	        if sha_str.is_empty() {
364	            return Ok(None);
365	        }
366	        Ok(CommitSha::parse(sha_str).ok())
367	    }
368	
369	    /// Lists non-merge commits reachable from `HEAD`, down to (exclusive)
370	    /// `since_ref` when given, keeping those that touch at least one of
371	    /// `pathspecs` (empty keeps every commit).
372	    ///
373	    /// `--full-history`: a commit touching a pathspec counts even when a
374	    /// later merge discarded its change (e.g. `merge -s ours`); default
375	    /// history simplification would silently drop it.
376	    ///
377	    /// A `since_ref` that is given but does not resolve is
378	    /// [`VcsError::RefNotFound`], never a silent unbounded walk.
379	    pub fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
380	        let mut args: Vec<String> = vec![
381	            "log".to_string(),
382	            "--no-merges".to_string(),
383	            "--full-history".to_string(),
384	            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
385	        ];
386	
387	        match since_ref {
388	            Some(r) => args.push(format!("{r}..HEAD")),
389	            None => args.push("HEAD".to_string()),
390	        }
391	
392	        if !pathspecs.is_empty() {
393	            args.push("--".to_string());
394	            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
395	        }
396	
397	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
398	        let output = self.runner.run("git", &arg_refs, &self.root)?;
399	
400	        if !output.success() {
401	            if let Some(r) = since_ref {
402	                if self.resolve_commit(r)?.is_none() {
403	                    return Err(VcsError::RefNotFound {
404	                        ref_name: r.to_string(),
405	                    });
406	                }
407	            }
408	            return Err(VcsError::Git(format!(
409	                "`git log` failed in `{}`: {}",
410	                self.root.display(),
411	                output.redacted_stderr()
412	            )));
413	        }
414	
415	        parse_git_log_output(&output.stdout, &self.root)
416	    }
417	
418	    /// Resolves every ref in `refs` to its commit with one `git rev-parse`.
419	    /// `None` when any of them does not resolve.
420	    pub fn resolve_commits(&self, refs: &[String]) -> Result<Option<Vec<CommitSha>>, VcsError> {
421	        let revs: Vec<String> = refs.iter().map(|r| format!("{r}^{{commit}}")).collect();
422	        let mut args = vec!["rev-parse"];
423	        args.extend(revs.iter().map(String::as_str));
424	        let output = self.runner.run("git", &args, &self.root)?;
425	        if !output.success() {
426	            return Ok(None);
427	        }
428	        let shas: Option<Vec<CommitSha>> = output.stdout_lines().map(|l| CommitSha::parse(l).ok()).collect();
429	        Ok(shas.filter(|shas| shas.len() == refs.len()))
430	    }
431	
432	    /// Paths, relative to the root and limited to it, that non-merge commits
433	    /// in `since_ref..HEAD` touched. Selects exactly what
434	    /// [`Self::commits_since`] filters on: `--full-history`, and a rename
435	    /// counts for both its old and new path.
436	    pub fn paths_changed_since(&self, since_ref: &str) -> Result<Vec<PathBuf>, VcsError> {
437	        let range = format!("{since_ref}..HEAD");
438	        self.name_only(&[
439	            "log",
440	            "--no-merges",
441	            "--full-history",
442	            "--no-renames",
443	            "--relative",
444	            "--name-only",
445	            "-z",
446	            "--format=",
447	            &range,
448	            "--",
449	        ])
450	    }
451	
452	    /// Tracked paths, relative to the root and limited to it, whose worktree
453	    /// contents differ from `since_ref`.
454	    pub fn paths_differing_from(&self, since_ref: &str) -> Result<Vec<PathBuf>, VcsError> {
455	        self.name_only(&[
456	            "diff",
457	            "--no-renames",
458	            "--relative",
459	            "--name-only",
460	            "-z",
461	            since_ref,
462	            "--",
463	        ])
464	    }
465	
466	    fn name_only(&self, args: &[&str]) -> Result<Vec<PathBuf>, VcsError> {
467	        let output = self.runner.run("git", args, &self.root)?;
468	        if !output.success() {
469	            return Err(VcsError::Git(format!(
470	                "`git {}` failed in `{}`: {}",
471	                args[0],
472	                self.root.display(),
473	                output.redacted_stderr()
474	            )));
475	        }
476	        Ok(output
477	            .stdout
478	            .split('\0')
479	            .map(|path| path.trim_start_matches('\n'))
480	            .filter(|path| !path.is_empty())
481	            .map(PathBuf::from)
482	            .collect())
483	    }
484	
485	    /// Creates the tag `name` at `target_sha`: annotated with `message`
486	    /// when `Some`, lightweight when `None`. Fails if the tag already
487	    /// exists. Writes a ref, so it requires an [`ApplyPermit`].
488	    pub fn create_tag(
489	        &self,
490	        name: &str,
491	        target_sha: &CommitSha,
492	        message: Option<&str>,
493	        sign: TagSignPolicy,
494	        _permit: &ApplyPermit,
495	    ) -> Result<(), VcsError> {
496	        let identity = match message {
497	            Some(_) => self.tagger_identity_override(target_sha)?,
498	            None => None,
499	        };
500	        let mut args: Vec<&str> = Vec::new();
501	        if let Some([name_config, email_config]) = &identity {
502	            args.extend(["-c", name_config.as_str(), "-c", email_config.as_str()]);
503	        }
504	        // `--` ends option parsing so `name` can never be misread as a flag.
505	        args.push("tag");
506	        if let Some(msg) = message {
507	            args.extend(["-a", "-m", msg]);
508	        }
509	        if matches!(sign, TagSignPolicy::ForceUnsigned) {
510	            args.push("--no-sign");
511	        }
512	        args.extend(["--", name, target_sha.as_str()]);
513	        let output = self.runner.run("git", &args, &self.root)?;
514	        if !output.success() {
515	            return Err(VcsError::Git(format!(
516	                "`git tag` failed in `{}`: {}",
517	                self.root.display(),
518	                output.redacted_stderr()
519	            )));
520	        }
521	        Ok(())
522	    }
