524	    /// `None` when Git can resolve a committer identity itself. Otherwise the
525	    /// target commit's committer, as `-c` overrides, since an annotated tag
526	    /// needs a tagger and a release runner's checkout often configures none.
527	    fn tagger_identity_override(&self, target_sha: &CommitSha) -> Result<Option<[String; 2]>, VcsError> {
528	        let ident = self.runner.run("git", &["var", "GIT_COMMITTER_IDENT"], &self.root)?;
529	        if ident.success() {
530	            return Ok(None);
531	        }
532	        let commit = self
533	            .runner
534	            .run("git", &["cat-file", "commit", target_sha.as_str()], &self.root)?;
535	        let committer = commit
536	            .stdout
537	            .lines()
538	            .take_while(|line| !line.is_empty())
539	            .find_map(|line| line.strip_prefix("committer "))
540	            .and_then(|ident| ident.split_once(" <"))
541	            .and_then(|(name, rest)| Some((name, rest.split_once('>')?.0)));
542	        match committer {
543	            Some((name, email)) if commit.success() && !name.is_empty() && !email.is_empty() => {
544	                Ok(Some([format!("user.name={name}"), format!("user.email={email}")]))
545	            }
546	            _ => Err(VcsError::Git(format!(
547	                "no Git identity for the tagger and could not read the committer of `{}`: {}",
548	                target_sha.as_str(),
549	                commit.redacted_stderr()
550	            ))),
551	        }
552	    }
