576	/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
577	/// produced by [`GitAccess::commits_since`] into [`GitCommit`]s, splitting
578	/// each raw message on its first blank line into `summary`/`body`.
579	fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
580	    let mut commits = Vec::new();
581	
582	    for record in stdout.split(RECORD_SEP) {
583	        // `tformat:`-style `--format=` output (the default when the format
584	        // string doesn't start with `format:`/`tformat:`) appends a
585	        // trailing newline after every entry; strip it rather than the
586	        // message's own content.
587	        let record = record.trim_end_matches('\n');
588	        if record.is_empty() {
589	            continue;
590	        }
591	
592	        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
593	            return Err(VcsError::Git(format!(
594	                "could not parse `git log` output in `{}` into commit records: expected a \
595	                 `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
596	                cwd.display()
597	            )));
598	        };
599	
600	        let sha = CommitSha::parse(sha_str).map_err(|e| {
601	            VcsError::Git(format!(
602	                "could not parse `git log` output in `{}`: invalid commit SHA `{sha_str}`: {e}",
603	                cwd.display()
604	            ))
605	        })?;
606	
607	        let message = message.replace("\r\n", "\n");
608	        let (summary, body) = match message.split_once("\n\n") {
609	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
610	            None => (message.trim_end().to_string(), None),
611	        };
612	
613	        commits.push(GitCommit { sha, summary, body });
614	    }
615	
616	    Ok(commits)
617	}
