669	            }),
670	            ["symbolic-ref", "--quiet", "HEAD"] => Ok(ok("refs/heads/main\n")),
671	            ["status", "--porcelain=v1", "-z", "--untracked-files=all"] => Ok(ok(status.clone())),
672	            other => panic!("unexpected Git trust command: {other:?}"),
673	        })
674	    }
